	      material[20].Cm=1.014;   material[20].k=0.5;     material[20].bf=1296; material[20].hm=0.15;    
	      //More Thermal Parameters: emiss[1], hc[W/m2.oC]
	      material[0].emiss=0 ;      material[0].MatInd=0;
