	      material[11].emiss=0 ;     material[11].MatInd=11;
	      material[12].emiss=0.023 ; material[12].MatInd=12;
	      material[13].emiss=0 ;     material[13].MatInd=13;
	      material[14].emiss=0.93 ;  material[14].MatInd=14;
	      material[15].emiss=0 ;     material[15].MatInd=15;
	      material[16].emiss=0.039 ; material[16].MatInd=16; // hc = 11.357[W/m2.oC] = 2 [Btu/h.ft2.oF] OK
	      material[17].emiss=0;      material[17].MatInd=17;
