	      material[19].emiss=0;      material[19].MatInd=19;
	      material[20].emiss=0;      material[20].MatInd=20;
	      //Reference for Coper:
	      //   "Heat Transfer", Frank M. White, Addison-Wesley Publishing Company, 1984
	      //   Appendix C - Properties of Metallic Solids
	      //Reference for Aluminium:
	      //   FOR THERMAL VALUES:
	      //   "1000 Solved Problems in HEAT TRANSFER - Schaum's Solved Problems Series", 
	      //    Donald R. Pitts, Leighton E. Sissom, McGraw-Hill Inc., 1991
	      //    Table B-1 - Properties of Metals
	      //   FOR CONDUCTIVITY:
	      //   "Electromagnetic Theory", Stratton, McGraw-Hill Book Company Inc., 1941
	      //    Appendix III - Conductivity of Various Materials


	      //INITIAL TISSUE and ENVIRONMENT TEMPERATURE AND H:
