		{
		//Sets the values of TotalTime and Delta T (in sec)
		case 1:	   dx=16.6666e-3; 	 dy=16.6666e-3;     dz=16.6666e-3;    DeltaT=22.777e-12;            break;
		case 2:	   dx=1.86e-3; 		 dy=1.11e-3;        dz=1.11e-3;       DeltaT=2e-12; 	            break;
		case 3:	   dx=3e-3;		 dy=3e-3;	    dz=1; 	      DeltaT=dx/(2*2.99792458e8);   break;
		case 4:    dx=16.6666e-3/2; 	 dy=16.6666e-3/2;   dz=16.6666e-3/2;  DeltaT=22.777e-12/2;          break;
		case 5:    dx=16.6666e-3/4; 	 dy=16.6666e-3/4;   dz=16.6666e-3/4;  DeltaT=22.777e-12/4;          break;
		case 6:    dx=16.6666e-3/10; 	 dy=16.6666e-3/10;  dz=16.6666e-3/10; DeltaT=22.777e-12/10;         break;
		case 7:    dx=812.8e-6/10;       dy=812.8e-6/10;    dz=812.8e-6/10;   DeltaT=3e-9;                  break;
		case 8:    dx=812.8e-6/2;        dy=812.8e-6/2;     dz=812.8e-6/2;    DeltaT=0.1;                   break;
		case 9:    dx=0.05;              dy=0.05;           dz=0.05;          DeltaT=0.01;                  break;
		case 10:   dx=0.05/5;            dy=0.05/5;         dz=0.05/5;        DeltaT=0.05;                  break;
		case 11:   dx=0.05/15;           dy=0.05/15;        dz=0.05/15;       DeltaT=0.01;                  break;
		case 12:   dx=0.05/35;           dy=0.05/35;        dz=0.05/35;       DeltaT=0.01;                  break;
		case 13:   dx=0.01; 		 dy=0.01;           dz=0.01;          DeltaT=10e-12; 	            break;
		case 14:   dx=1.5e-2;            dy=1.5e-2;         dz=1.5e-2;        DeltaT=14e-12;                break;
		default:   dx=1.86e-3; 		 dy=1.11e-3;   	    dz=1.11e-3;       DeltaT=2e-12;                 break;
		}	      	      
